1	package mevwatch
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"sort"
11		"strconv"
12		"strings"
13		"syscall"
14	)
15	
16	// Offline alerting turns conclusions already stored in an archive into
17	// alert processing records. It never re-runs detection: a record always
18	// reflects the finding, the rule version and the parameters that were in
19	// force when the block was archived.
20	
21	// Alert statuses. A finding above the generation threshold becomes an
22	// "alert"; a finding that matches one or more registered suppression
23	// conditions at its block height becomes "suppressed" instead.
24	const (
25		AlertStatusAlert      = "alert"
26		AlertStatusSuppressed = "suppressed"
27	)
28	
29	// Suppression condition kinds.
30	const (
31		SuppressSandwich     = "sandwich"
32		SuppressDisplacement = "displacement"
33	)
34	
35	// ErrUnknownKind reports a conclusion/condition kind that is neither
36	// sandwich nor displacement.
37	var ErrUnknownKind = errors.New("unknown kind")
38	
39	// ErrSuppressionConflict reports re-registering an existing suppression ID
40	// with different content.
41	var ErrSuppressionConflict = errors.New("suppression already registered with different content")
42	
43	// ErrUnknownSuppression reports revoking a condition ID that is not
44	// registered in the archive (including the empty archive).
45	var ErrUnknownSuppression = errors.New("unknown suppression condition")
46	
47	// SuppressionHit records one suppression condition that matched an event.
48	type SuppressionHit struct {
49		ID     string `json:"id"`
50		Reason string `json:"reason"`
51	}
52	
53	// ProcessingRecord is one fully resolved alerting outcome. Its identity is
54	// (chain, block hash, victim tx hash, conclusion kind, channel): once a
55	// record exists for that identity, no later import, wider or overlapping
56	// height range, rule-version switch or restart can produce it again. The
57	// record keeps the complete block identity, pool, conclusion, raw swap
58	// evidence, the detection version and its parameters, the threshold used at
59	// generation time, and every suppression condition that matched.
60	type ProcessingRecord struct {
61		ChainID      string           `json:"chainId"`
62		BlockHash    string           `json:"blockHash"`
63		BlockNumber  uint64           `json:"blockNumber"`
64		Pool         string           `json:"pool"`
65		Channel      string           `json:"channel"`
66		Finding      ReportFinding    `json:"finding"`
67		Version      RuleVersion      `json:"version"`
68		MinSeverity  int              `json:"minSeverity"`
69		Status       string           `json:"status"`
70		Suppressions []SuppressionHit `json:"suppressions"`
71	}
72	
73	func (r ProcessingRecord) identity() alertKey {
74		return alertKey{
75			chainID:   r.ChainID,
76			blockHash: r.BlockHash,
77			txHash:    r.Finding.TxHash,
78			kind:      r.Finding.Kind,
79			channel:   r.Channel,
80		}
81	}
82	
83	// Suppression is one registered suppression condition. Every field matches
84	// exactly (the pool is matched against the pool of the victim swap's
85	// original exchange record), and an event at height h is covered when
86	// StartHeight <= h <= EndHeight.
87	//
88	// Revoked marks a condition whose user has withdrawn it. A revoked
89	// condition is kept for audit but never matches later processing; the
90	// field is always serialized (an absent value in an old archive decodes
91	// to false, i.e. not revoked) and cannot be set through a registration
92	// document. Revocation applies to findings processed afterwards only —
93	// event height never decides when it takes effect.
94	type Suppression struct {
95		ID          string `json:"id"`
96		ChainID     string `json:"chainId"`
97		Pool        string `json:"pool"`
98		Kind        string `json:"kind"`
99		Channel     string `json:"channel"`
100		StartHeight uint64 `json:"startHeight"`
101		EndHeight   uint64 `json:"endHeight"`
102		Reason      string `json:"reason"`
103		Revoked     bool   `json:"revoked"`
104	}
105	
106	// covers reports whether the suppression applies to an event on chain at
107	// height in the given pool/kind/channel. Matching depends only on the
108	// event's height, never on operation time, import order or the archive's
109	// highest block.
110	func (s Suppression) covers(chainID, pool, kind, channel string, height uint64) bool {
111		return s.ChainID == chainID && s.Pool == pool && s.Kind == kind && s.Channel == channel &&
112			s.StartHeight <= height && height <= s.EndHeight
113	}
114	
115	// alertKey is the deduplication identity of a processing record.
116	type alertKey struct {
117		chainID   string
118		blockHash string
119		txHash    string
120		kind      string
121		channel   string
122	}
123	
124	// suppressionSpec mirrors one suppression registration document. Pointers
125	// distinguish missing fields from explicit zero values; heights are parsed
126	// separately as unsigned 64-bit integers.
127	type suppressionSpec struct {
128		ID          *string `json:"id"`
129		ChainID     *string `json:"chainId"`
130		Pool        *string `json:"pool"`
131		Kind        *string `json:"kind"`
132		Channel     *string `json:"channel"`
133		StartHeight *uint64 `json:"startHeight"`
134		EndHeight   *uint64 `json:"endHeight"`
135		Reason      *string `json:"reason"`
136	}
137	
138	func nonEmpty(field string, v *string) (string, error) {
139		if v == nil {
140			return "", fmt.Errorf("%s is required (non-empty string)", field)
141		}
142		if strings.TrimSpace(*v) == "" {
143			return "", fmt.Errorf("%s must be a non-empty string", field)
144		}
145		return *v, nil
146	}
147	
148	// suppressionFields lists every field name a registration document may
149	// declare, in the struct's JSON spelling.
150	var suppressionFields = []string{"id", "chainId", "pool", "kind", "channel", "startHeight", "endHeight", "reason"}
151	
152	// canonicalSuppressionField resolves an unescaped object key to a known
153	// field name. Like the JSON decoder itself, a key that differs only in
154	// case still names the same field.
155	func canonicalSuppressionField(key string) (string, bool) {
156		for _, f := range suppressionFields {
157			if f == key {
158				return f, true
159			}
160		}
161		for _, f := range suppressionFields {
162			if strings.EqualFold(f, key) {
163				return f, true
164			}
165		}
166		return "", false
167	}
168	
169	// validateSuppressionDocument checks the raw registration input
170	// structurally before any field is read: it must hold exactly one complete
171	// JSON object — leading and trailing whitespace is fine, but empty input,
172	// arrays, null, scalars and incomplete objects are not, and no byte other
173	// than whitespace may follow the closing brace (a second object, an extra
174	// } or ] or any other JSON value is rejected). Inside the object every
175	// known field may be declared at most once: field names are compared after
176	// JSON unescaping, and two spellings that resolve to the same field —
177	// including ones differing only in case, like channel and CHANNEL — count
178	// as one duplicate declaration even when both carry the same value.
179	func validateSuppressionDocument(raw []byte) error {
180		dec := json.NewDecoder(bytes.NewReader(raw))
181		tok, err := dec.Token()
182		if err != nil {
183			return fmt.Errorf("invalid suppression spec: %w", err)
184		}
185		if d, ok := tok.(json.Delim); !ok || d != '{' {
186			return errors.New("invalid suppression spec: expected a single JSON object")
187		}
188		seen := make(map[string]string, len(suppressionFields))
189		for dec.More() {
190			kt, err := dec.Token()
191			if err != nil {
192				return fmt.Errorf("invalid suppression spec: %w", err)
193			}
194			key := kt.(string)
195			if canonical, known := canonicalSuppressionField(key); known {
196				if first, dup := seen[canonical]; dup {
197					return fmt.Errorf("invalid suppression spec: duplicate field %q (declared as %q and %q)", canonical, first, key)
198				}
199				seen[canonical] = key
200			}
201			var value json.RawMessage
202			if err := dec.Decode(&value); err != nil {
203				return fmt.Errorf("invalid suppression spec: %w", err)
204			}
205		}
206		if _, err := dec.Token(); err != nil { // the closing brace
207			return fmt.Errorf("invalid suppression spec: %w", err)
208		}
209		var extra json.RawMessage
210		if err := dec.Decode(&extra); err != io.EOF {
211			return errors.New("invalid suppression spec: unexpected trailing data")
212		}
213		return nil
214	}
215	
216	// ParseSuppression validates one registration document. Only sandwich and
217	// displacement kinds exist, every text field must be non-empty, heights are
218	// unsigned 64-bit integers and the start height must not exceed the end
219	// height.
220	func ParseSuppression(raw []byte) (Suppression, error) {
221		if err := validateSuppressionDocument(raw); err != nil {
222			return Suppression{}, err
223		}
224		var spec suppressionSpec
225		dec := json.NewDecoder(bytes.NewReader(raw))
226		dec.DisallowUnknownFields()
227		if err := dec.Decode(&spec); err != nil {
228			return Suppression{}, fmt.Errorf("invalid suppression spec: %w", err)
229		}
230		id, err := nonEmpty("id", spec.ID)
231		if err != nil {
232			return Suppression{}, err
233		}
234		chainID, err := nonEmpty("chainId", spec.ChainID)
235		if err != nil {
236			return Suppression{}, err
237		}
238		pool, err := nonEmpty("pool", spec.Pool)
239		if err != nil {
240			return Suppression{}, err
241		}
242		kind, err := nonEmpty("kind", spec.Kind)
243		if err != nil {
244			return Suppression{}, err
245		}
246		if kind != SuppressSandwich && kind != SuppressDisplacement {
247			return Suppression{}, fmt.Errorf("%w: %q (want sandwich or displacement)", ErrUnknownKind, kind)
248		}
249		channel, err := nonEmpty("channel", spec.Channel)
250		if err != nil {
251			return Suppression{}, err
252		}
253		if spec.StartHeight == nil {
254			return Suppression{}, errors.New("startHeight is required (unsigned 64-bit integer)")
255		}
256		if spec.EndHeight == nil {
257			return Suppression{}, errors.New("endHeight is required (unsigned 64-bit integer)")
258		}
259		if *spec.StartHeight > *spec.EndHeight {
260			return Suppression{}, fmt.Errorf("startHeight %d must not exceed endHeight %d", *spec.StartHeight, *spec.EndHeight)
261		}
262		reason, err := nonEmpty("reason", spec.Reason)
263		if err != nil {
264			return Suppression{}, err
265		}
266		return Suppression{
267			ID:          id,
268			ChainID:     chainID,
269			Pool:        pool,
270			Kind:        kind,
271			Channel:     channel,
272			StartHeight: *spec.StartHeight,
273			EndHeight:   *spec.EndHeight,
274			Reason:      reason,
275		}, nil
276	}
277	
278	// ParseHeight parses a non-negative 64-bit integer height. Signs, fractions,
279	// blanks and values above 2^64-1 are rejected.
280	func ParseHeight(text string) (uint64, error) {
281		if text == "" {
282			return 0, errors.New("height must be a non-empty unsigned 64-bit integer")
283		}
284		h, err := strconv.ParseUint(text, 10, 64)
285		if err != nil {
286			return 0, fmt.Errorf("invalid height %q: %w", text, err)
287		}
288		return h, nil
289	}
290	
291	// ValidateSeverity accepts the integer threshold range 1..5 inclusive; the
292	// threshold itself counts as a hit.
293	func ValidateSeverity(severity int) error {
294		if severity < 1 || severity > 5 {
295			return fmt.Errorf("minSeverity must be between 1 and 5, got %d", severity)
296		}
297		return nil
298	}
299	
300	// suppressionEqual reports whether two conditions carry identical
301	// registration content. Revoked state is intentionally excluded: retrying
302	// the same document is idempotent even after the condition was revoked
303	// (and never re-enables it), while differing content still conflicts.
304	func suppressionEqual(a, b Suppression) bool {
305		return a.ID == b.ID &&
306			a.ChainID == b.ChainID &&
307			a.Pool == b.Pool &&
308			a.Kind == b.Kind &&
309			a.Channel == b.Channel &&
310			a.StartHeight == b.StartHeight &&
311			a.EndHeight == b.EndHeight &&
312			a.Reason == b.Reason
313	}
314	
315	// matchSuppressions returns every active condition covering the event,
316	// sorted by ID in lexicographic order so overlapping conditions are
317	// reported deterministically. Revoked conditions are skipped: they no
318	// longer apply to conclusions processed after the revocation.
319	func matchSuppressions(conds []Suppression, chainID, pool, kind, channel string, height uint64) []SuppressionHit {
320		hits := []SuppressionHit{}
321		for _, s := range conds {
322			if s.Revoked {
323				continue
324			}
325			if s.covers(chainID, pool, kind, channel, height) {
326				hits = append(hits, SuppressionHit{ID: s.ID, Reason: s.Reason})
327			}
328		}
329		sort.Slice(hits, func(i, j int) bool { return hits[i].ID < hits[j].ID })
330		return hits
331	}
332	
333	// victimPool returns the pool of the victim swap inside the finding's raw
334	// evidence. The victim is the swap whose TxHash matches the finding; the
335	// evidence ordering and count vary by conclusion kind, so the pool is read
336	// off the original exchange record rather than inferred from position.
337	func victimPool(f ReportFinding) (string, bool) {
338		for _, s := range f.Evidence {
339			if s.TxHash == f.TxHash {
340				return s.Pool, true
341			}
342		}
343		return "", false
344	}
345	
346	// sortRecords orders processing records by height, block hash, tx hash and
347	// kind ascending. Channel stays out of the ordering key: generation runs for
348	// one channel, history may span several.
349	func sortRecords(records []ProcessingRecord) {
350		sort.Slice(records, func(i, j int) bool {
351			a, b := records[i], records[j]
352			if a.BlockNumber != b.BlockNumber {
353				return a.BlockNumber < b.BlockNumber
354			}
355			if a.BlockHash != b.BlockHash {
356				return a.BlockHash < b.BlockHash
357			}
358			if a.Finding.TxHash != b.Finding.TxHash {
359				return a.Finding.TxHash < b.Finding.TxHash
360			}
361			return a.Finding.Kind < b.Finding.Kind
362		})
363	}
364	
365	// GenerateAlerts turns archived conclusions in the inclusive range
366	// [startHeight, endHeight] on chainID for channel into new processing
367	// records. Detection is not re-run: the archived finding, evidence and rule
368	// version are reused. A finding at least minSeverity is processed; findings
369	// below the threshold leave no record, so lowering the threshold later can
370	// still produce them. Every already-processed identity is skipped, which
371	// makes repeated imports, repeated generation, wider or overlapping ranges,
372	// version switches and restarts idempotent. Channels are independent, and
373	// blocks at the same height with different hashes are handled separately.
374	//
375	// All new records of one call are committed together or not at all. The
376	// returned slice contains only records created by this call (alerts and
377	// suppressions distinguished), sorted by height, block hash, tx hash and
378	// kind; an empty result serializes as [].
379	func GenerateAlerts(dir, chainID, channel string, startHeight, endHeight uint64, minSeverity int) ([]ProcessingRecord, error) {
380		if strings.TrimSpace(chainID) == "" {
381			return nil, errors.New("chainId must be a non-empty string")
382		}
383		if strings.TrimSpace(channel) == "" {
384			return nil, errors.New("channel must be a non-empty name")
385		}
386		if err := ValidateSeverity(minSeverity); err != nil {
387			return nil, err
388		}
389		if startHeight > endHeight {
390			return nil, fmt.Errorf("startHeight %d must not exceed endHeight %d", startHeight, endHeight)
391		}
392		if err := os.MkdirAll(dir, 0o755); err != nil {
393			return nil, err
394		}
395		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
396		if err != nil {
397			return nil, err
398		}
399		defer lock.Close()
400	
401		data, err := readArchive(dir)
402		if err != nil {
403			return nil, err
404		}
405		processed := make(map[alertKey]struct{}, len(data.AlertRecords))
406		for _, r := range data.AlertRecords {
407			processed[r.identity()] = struct{}{}
408		}
409	
410		created := []ProcessingRecord{}
411		for _, rec := range data.Records {
412			if rec.ChainID != chainID {
413				continue
414			}
415			height := uint64(rec.BlockNumber)
416			if height < startHeight || height > endHeight {
417				continue
418			}
419			version := rec.ruleVersion()
420			for _, f := range rec.Findings {
421				if f.Severity < minSeverity {
422					// Below the threshold: no record is written, so the event
423					// stays eligible after a later threshold reduction.
424					continue
425				}
426				key := alertKey{
427					chainID:   rec.ChainID,
428					blockHash: rec.BlockHash,
429					txHash:    f.TxHash,
430					kind:      f.Kind,
431					channel:   channel,
432				}
433				if _, ok := processed[key]; ok {
434					continue
435				}
436				pool, ok := victimPool(f)
437				if !ok {
438					return nil, fmt.Errorf("archive is corrupted: archived finding for block %s/%s tx %s has no victim swap in its evidence",
439						rec.ChainID, rec.BlockHash, f.TxHash)
440				}
441				hits := matchSuppressions(data.Suppressions, rec.ChainID, pool, f.Kind, channel, height)
442				status := AlertStatusAlert
443				if len(hits) > 0 {
444					status = AlertStatusSuppressed
445				}
446				record := ProcessingRecord{
447					ChainID:      rec.ChainID,
448					BlockHash:    rec.BlockHash,
449					BlockNumber:  height,
450					Pool:         pool,
451					Channel:      channel,
452					Finding:      f,
453					Version:      version,
454					MinSeverity:  minSeverity,
455					Status:       status,
456					Suppressions: hits,
457				}
458				created = append(created, record)
459				processed[key] = struct{}{}
460			}
461		}
462		sortRecords(created)
463		if len(created) > 0 {
464			data.AlertRecords = append(data.AlertRecords, created...)
465			if err := writeArchiveAtomic(dir, data); err != nil {
466				return nil, err
467			}
468		}
469		return created, nil
470	}
471	
472	// AlertHistory returns stored processing records on chainID for channel in
473	// the inclusive range [startHeight, endHeight]. It only reads the archive;
474	// suppressions registered afterwards cannot alter the stored content.
475	func AlertHistory(dir, chainID, channel string, startHeight, endHeight uint64) ([]ProcessingRecord, error) {
476		if strings.TrimSpace(chainID) == "" {
477			return nil, errors.New("chainId must be a non-empty string")
478		}
479		if strings.TrimSpace(channel) == "" {
480			return nil, errors.New("channel must be a non-empty name")
481		}
482		if startHeight > endHeight {
483			return nil, fmt.Errorf("startHeight %d must not exceed endHeight %d", startHeight, endHeight)
484		}
485		if _, serr := os.Stat(dir); serr != nil {
486			if errors.Is(serr, os.ErrNotExist) {
487				return []ProcessingRecord{}, nil
488			}
489			return nil, serr
490		}
491		lock, err := lockArchive(dir, syscall.LOCK_SH)
492		if err != nil {
493			return nil, err
494		}
495		defer lock.Close()
496	
497		data, err := readArchive(dir)
498		if err != nil {
499			return nil, err
500		}
501		out := []ProcessingRecord{}
502		for _, r := range data.AlertRecords {
503			if r.ChainID != chainID || r.Channel != channel {
504				continue
505			}
506			if r.BlockNumber < startHeight || r.BlockNumber > endHeight {
507				continue
508			}
509			out = append(out, r)
510		}
511		sortRecords(out)
512		return out, nil
513	}
514	
515	// RegisterSuppression validates raw and stores one suppression condition in
516	// the archive. Re-registering the same ID with identical content succeeds
517	// without adding anything (created is false) — this stays true after the
518	// condition was revoked and never re-enables it; the same ID with different
519	// content is rejected. New conditions only affect conclusions that have not
520	// been processed yet: historical alerts are never rewritten as suppressed,
521	// and suppressed records are not re-alerted when a condition's range ends.
522	// The registration document cannot set revoked state.
523	func RegisterSuppression(dir string, raw []byte) (s Suppression, created bool, err error) {
524		s, err = ParseSuppression(raw)
525		if err != nil {
526			return Suppression{}, false, err
527		}
528		if err := os.MkdirAll(dir, 0o755); err != nil {
529			return Suppression{}, false, err
530		}
531		lock, lerr := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
532		if lerr != nil {
533			return Suppression{}, false, lerr
534		}
535		defer lock.Close()
536	
537		data, err := readArchive(dir)
538		if err != nil {
539			return Suppression{}, false, err
540		}
541		for _, existing := range data.Suppressions {
542			if existing.ID == s.ID {
543				if suppressionEqual(existing, s) {
544					return existing, false, nil
545				}
546				return Suppression{}, false, fmt.Errorf("%w: %s", ErrSuppressionConflict, s.ID)
547			}
548		}
549		data.Suppressions = append(data.Suppressions, s)
550		if err := writeArchiveAtomic(dir, data); err != nil {
551			return Suppression{}, false, err
552		}
553		return s, true, nil
554	}
555	
556	// RevokeSuppression withdraws the condition with the given exact ID. The
557	// first successful revocation returns changed=true and the full condition
558	// with Revoked set; revoking the same ID again succeeds with changed=false.
559	// A blank ID is rejected, and an ID that was never registered — including
560	// any ID in an empty archive — returns ErrUnknownSuppression. The revoked
561	// condition is retained (still listed) but stops matching conclusions
562	// processed from now on; it cannot be revived, a fresh ID is required to
563	// suppress again.
564	//
565	// The revocation is committed atomically under the archive lock: a busy
566	// archive, a corrupted one or a failed save leaves every condition, report
567	// and processing record untouched. One generation run always sees either
568	// the pre- or the post-revocation condition set in full.
569	func RevokeSuppression(dir, id string) (s Suppression, changed bool, err error) {
570		if strings.TrimSpace(id) == "" {
571			return Suppression{}, false, errors.New("suppression id must be a non-empty string")
572		}
573		if err := os.MkdirAll(dir, 0o755); err != nil {
574			return Suppression{}, false, err
575		}
576		lock, lerr := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
577		if lerr != nil {
578			return Suppression{}, false, lerr
579		}
580		defer lock.Close()
581	
582		data, err := readArchive(dir)
583		if err != nil {
584			return Suppression{}, false, err
585		}
586		for i := range data.Suppressions {
587			if data.Suppressions[i].ID != id {
588				continue
589			}
590			if data.Suppressions[i].Revoked {
591				return data.Suppressions[i], false, nil
592			}
593			data.Suppressions[i].Revoked = true
594			if err := writeArchiveAtomic(dir, data); err != nil {
595				return Suppression{}, false, err
596			}
597			return data.Suppressions[i], true, nil
598		}
599		return Suppression{}, false, fmt.Errorf("%w: %s", ErrUnknownSuppression, id)
600	}
601	
602	// ListSuppressions returns every suppression condition stored in the
603	// archive, ordered by ID. A read on an absent archive returns an empty list.
604	func ListSuppressions(dir string) ([]Suppression, error) {
605		if _, serr := os.Stat(dir); serr != nil {
606			if errors.Is(serr, os.ErrNotExist) {
607				return []Suppression{}, nil
608			}
609			return nil, serr
610		}
611		lock, err := lockArchive(dir, syscall.LOCK_SH)
612		if err != nil {
613			return nil, err
614		}
615		defer lock.Close()
616	
617		data, err := readArchive(dir)
618		if err != nil {
619			return nil, err
620		}
621		out := append([]Suppression(nil), data.Suppressions...)
622		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
623		if out == nil {
624			out = []Suppression{}
625		}
626		return out, nil
627	}
