342		builtinSpec := `{"id":"builtin","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`
343		if _, _, err := RegisterVersion(dir, []byte(builtinSpec)); err == nil {
344			t.Fatal("registering over the built-in id must fail")
345		}
346		// Enable persists and is visible to a fresh reader.
347		if _, err := EnableVersion(dir, "strict"); err != nil {
348			t.Fatal(err)
349		}
350		_, enabled, err = ListVersions(dir)
351		if err != nil {
352			t.Fatal(err)
353		}
354		if enabled != "strict" {
355			t.Fatalf("enabled = %q, want strict", enabled)
356		}
357		got, err := GetVersion(dir, "strict")
358		if err != nil || got != v {
359			t.Fatalf("GetVersion = %+v, %v", got, err)
360		}
361		// Enabling an unknown version fails and changes nothing.
362		if _, err := EnableVersion(dir, "nope"); !errors.Is(err, ErrUnknownVersion) {
363			t.Fatalf("got %v, want ErrUnknownVersion", err)
364		}
365		_, enabled, _ = ListVersions(dir)
366		if enabled != "strict" {
367			t.Fatalf("failed enable changed enabled version to %q", enabled)
368		}
369		// The built-in version is queryable without registration.
370		b, err := GetVersion(dir, BuiltinVersionID)
371		if err != nil {
372			t.Fatal(err)
373		}
374		if b.Rules.Sandwich != (SandwichRule{Enabled: true, Severity: 3}) ||
375			b.Rules.Displacement != (DisplacementRule{Enabled: true, Severity: 2, Multiplier: 2}) {
376			t.Fatalf("builtin params wrong: %+v", b)
377		}
