590			t.Fatalf("raw swap evidence missing: %+v", result.Swaps)
591		}
592		// 0xva: displacement under builtin, nothing under strict -> removed.
593		if len(result.Removed) != 1 || result.Removed[0].TxHash != "0xva" {
594			t.Fatalf("removed = %+v", result.Removed)
595		}
596		// 0xvb: sandwich under both, severity 3 -> 5: changed only, not added+removed.
597		if len(result.Changed) != 1 || result.Changed[0].TxHash != "0xvb" {
598			t.Fatalf("changed = %+v", result.Changed)
599		}
600		if result.Changed[0].Original.Severity != 3 || result.Changed[0].Compared.Severity != 5 {
601			t.Fatalf("change detail wrong: %+v", result.Changed[0])
602		}
603		if len(result.Added) != 0 {
604			t.Fatalf("added = %+v", result.Added)
605		}
606		// Both full conclusion sets are present.
607		if len(result.OriginalFindings) != 2 || len(result.ComparedFindings) != 1 {
608			t.Fatalf("findings sets wrong: %+v / %+v", result.OriginalFindings, result.ComparedFindings)
609		}
610		// Compare must not modify the archived report or the enabled version.
611		after, err := Query(dir, "1", "0xcmp")
612		if err != nil {
613			t.Fatal(err)
614		}
615		if after.Version.ID != BuiltinVersionID || len(after.Findings) != 2 || after.Findings[1].Severity != 2 {
616			t.Fatalf("compare modified the archived report: %+v", after)
617		}
618		_, enabled, _ := ListVersions(dir)
619		if enabled != BuiltinVersionID {
620			t.Fatalf("compare changed enabled version to %q", enabled)
621		}
622	}
623	
624	func TestCompareAddedAndSorted(t *testing.T) {
625		dir := t.TempDir()
626		// Builtin flags nothing (front gas 15 < 2*10? no: 15 > 20 false... 15 < 20, no displacement).
627		// A looser version (multiplier 1 not allowed; use severity-only change via multiplier 2 with
628		// front 25 > 20 for 0xvc, and front 21 > 20 for 0xva) — instead register a version with
629		// multiplier 2 but higher sandwich severity to also produce a change; keep it simple:
630		// builtin: no findings; strict2 (multiplier 2, but front 25/21 flagged): two added, hash-sorted.
631		input := `{"chainId":"1","blockHash":"0xadd","blockNumber":3,"swaps":[` +
632			`{"TxHash":"0xfz","Pool":"p1","Trader":"w","In":1,"Out":1,"GasPrice":25,"Index":0},` +
633			`{"TxHash":"0xvz","Pool":"p1","Trader":"u","In":1,"Out":1,"GasPrice":10,"Index":1},` +
634			`{"TxHash":"0xfa","Pool":"p2","Trader":"w","In":1,"Out":1,"GasPrice":21,"Index":2},` +
635			`{"TxHash":"0xva","Pool":"p2","Trader":"u","In":1,"Out":1,"GasPrice":10,"Index":3}]}`
636		reports := replay(t, dir, input)
637		if len(reports[0].Findings) != 2 {
638			t.Fatalf("setup: builtin should flag both (25>20, 21>20): %+v", reports[0].Findings)
639		}
640		// Compare against a version with multiplier 3: 25 > 30 false, 21 > 30 false -> both removed, sorted.
641		spec := `{"id":"x3","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":3}}}`
642		register(t, dir, spec)
643		result, err := Compare(dir, "1", "0xadd", "x3")
