647		if len(result.Removed) != 2 || result.Removed[0].TxHash != "0xva" || result.Removed[1].TxHash != "0xvz" {
648			t.Fatalf("removed not sorted by tx hash: %+v", result.Removed)
649		}
650		// Reverse direction: comparing a no-finding record against builtin adds them.
651		// Use the same block under x3 archived in a second archive for the added case.
652		dir2 := t.TempDir()
653		register(t, dir2, spec)
654		if _, err := ReplayWithVersion(strings.NewReader(input), dir2, "x3"); err != nil {
655			t.Fatal(err)
656		}
657		result2, err := Compare(dir2, "1", "0xadd", BuiltinVersionID)
658		if err != nil {
659			t.Fatal(err)
660		}
661		if len(result2.Added) != 2 || result2.Added[0].TxHash != "0xva" || result2.Added[1].TxHash != "0xvz" {
662			t.Fatalf("added not sorted by tx hash: %+v", result2.Added)
663		}
664		if result2.OriginalVersion.ID != "x3" {
665			t.Fatalf("original version wrong: %+v", result2.OriginalVersion)
666		}
