func trailingTokenName(b byte) string {
	switch b {
	case '{':
		return "object"
	case '[':
		return "array"
	case '}':
		return "extra closing brace '}'"
	case ']':
		return "extra closing bracket ']'"
	case '"':
		return "string"
	case 't', 'f':
		return "boolean"
	case 'n':
		return "null"
	default:
		if (b >= '0' && b <= '9') || b == '-' {
			return "number"
		}
		return fmt.Sprintf("unexpected character %q", rune(b))
